 96	/**
 97	 * Extends all the API calls to set baggage automatically.
 98	 */
 99	const ApiGateway = new Proxy(Apis(), {
100	  get(target, prop, receiver) {
101	    const originalFunction = Reflect.get(target, prop, receiver);
102	
103	    if (typeof originalFunction !== 'function') {
104	      return originalFunction;
105	    }
106	
107	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
108	    return function (...args: any[]) {
109	      const baggage = propagation.getActiveBaggage() || propagation.createBaggage();
110	      const newBaggage = baggage
111	        .setEntry(AttributeNames.SESSION_ID, { value: userId })
112	        .setEntry(AttributeNames.ENDUSER_ID, { value: userId });
113	      const newContext = propagation.setBaggage(context.active(), newBaggage);
114	      return context.with(newContext, () => {
115	        return Reflect.apply(originalFunction, undefined, args);
116	      });
117	    };
118	  },
119	});
