  4	import { createContext, useCallback, useContext, useMemo } from 'react';
  5	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
  6	import ApiGateway from '../gateways/Api.gateway';
  7	import { CartItem, OrderResult, PlaceOrderRequest } from '../protos/demo';
  8	import { IProductCart } from '../types/Cart';
  9	import { useCurrency } from './Currency.provider';
 10	
 11	interface IContext {
 12	  cart: IProductCart;
 13	  addItem(item: CartItem): void;
 14	  updateItemQuantity(productId: string, newQuantity: number): void;
 15	  emptyCart(): void;
 16	  placeOrder(order: PlaceOrderRequest): Promise<OrderResult>;
 17	}
 18	
 19	export const Context = createContext<IContext>({
 20	  cart: { userId: '', items: [] },
 21	  addItem: () => {},
 22	  updateItemQuantity: () => {},
 23	  emptyCart: () => {},
 24	  placeOrder: () => Promise.resolve({} as OrderResult),
 25	});
 26	
 27	interface IProps {
 28	  children: React.ReactNode;
 29	}
 30	
 31	export const useCart = () => useContext(Context);
 32	
 33	const CartProvider = ({ children }: IProps) => {
 34	  const { selectedCurrency } = useCurrency();
 35	  const queryClient = useQueryClient();
 36	  const mutationOptions = useMemo(
 37	    () => ({
 38	      onSuccess: () => {
 39	        queryClient.invalidateQueries({ queryKey: ['cart'] });
 40	      },
 41	    }),
 42	    [queryClient]
 43	  );
 44	
 45	  const { data: cart = { userId: '', items: [] } } = useQuery({
 46	    queryKey: ['cart', selectedCurrency],
 47	    queryFn: () => ApiGateway.getCart(selectedCurrency),
 48	  });
 49	  const addCartMutation = useMutation({
 50	    mutationFn: ApiGateway.addCartItem,
 51	    ...mutationOptions,
 52	  });
 53	
 54	  const emptyCartMutation = useMutation({
 55	    mutationFn: ApiGateway.emptyCart,
 56	    ...mutationOptions,
 57	  });
 58	
 59	  const placeOrderMutation = useMutation({
 60	    mutationFn: ApiGateway.placeOrder,
 61	    ...mutationOptions,
 62	  });
 63	
 64	  const addItem = useCallback(
 65	    (item: CartItem) => addCartMutation.mutateAsync({ ...item, currencyCode: selectedCurrency }),
 66	    [addCartMutation, selectedCurrency]
 67	  );
 68	
 69	  const updateItemQuantity = useCallback(
 70	    (productId: string, newQuantity: number) => {
 71	      const existing = cart.items.find(i => i.productId === productId);
 72	      const delta = newQuantity - (existing?.quantity ?? 0);
 73	      if (delta !== 0) {
 74	        addCartMutation.mutateAsync({ productId, quantity: delta, currencyCode: selectedCurrency });
 75	      }
 76	    },
 77	    [addCartMutation, cart.items, selectedCurrency]
 78	  );
 79	  const emptyCart = useCallback(() => emptyCartMutation.mutateAsync(), [emptyCartMutation]);
 80	  const placeOrder = useCallback(
 81	    (order: PlaceOrderRequest) => placeOrderMutation.mutateAsync({ ...order, currencyCode: selectedCurrency }),
 82	    [placeOrderMutation, selectedCurrency]
 83	  );
 84	
 85	  const value = useMemo(() => ({ cart, addItem, updateItemQuantity, emptyCart, placeOrder }), [cart, addItem, updateItemQuantity, emptyCart, placeOrder]);
 86	
 87	  return <Context.Provider value={value}>{children}</Context.Provider>;
 88	};
