14	const InstrumentationMiddleware = (handler: NextApiHandler): NextApiHandler => {
15	  return async (request, response) => {
16	    const span = trace.getSpan(context.active()) as Span;
17	    const urlPath = request.url?.split('?', 1)[0];
18	
19	    let httpStatus = 200;
20	    try {
21	      await runWithSpan(span, async () => handler(request, response));
22	      httpStatus = response.statusCode;
23	      logger.info(
24	        {
25	          [ATTR_HTTP_REQUEST_METHOD]: request.method,
26	          [ATTR_URL_PATH]: urlPath,
27	          [ATTR_HTTP_RESPONSE_STATUS_CODE]: httpStatus,
28	        },
29	        'API request completed'
30	      );
31	    } catch (error) {
32	      span.recordException(error as Exception);
33	      span.setStatus({ code: SpanStatusCode.ERROR });
34	      httpStatus = 500;
35	      logger.error(
36	        {
37	          err: error,
38	          [ATTR_HTTP_REQUEST_METHOD]: request.method,
39	          [ATTR_URL_PATH]: urlPath,
40	          [ATTR_HTTP_RESPONSE_STATUS_CODE]: httpStatus,
41	        },
42	        'API request failed'
43	      );
44	      throw error;
45	    } finally {
46	      span.setAttribute(SemanticAttributes.HTTP_STATUS_CODE, httpStatus);
47	    }
48	  };
49	};
50	
51	async function runWithSpan(parentSpan: Span, fn: () => Promise<unknown>) {
52	  const ctx = trace.setSpan(context.active(), parentSpan);
53	  return await context.with(ctx, fn);
54	}
55	
56	export default InstrumentationMiddleware;
