  6	import getFrontendProxyURL from "@/utils/Settings";
  7	
  8	interface IRequestParams {
  9	  url: string;
 10	  body?: object;
 11	  method?: "GET" | "POST" | "PUT" | "DELETE";
 12	  queryParams?: Record<string, any>;
 13	  headers?: Record<string, string>;
 14	}
 15	
 16	const request = async <T>({
 17	  url = "",
 18	  method = "GET",
 19	  body,
 20	  queryParams = {},
 21	  headers = {
 22	    "content-type": "application/json",
 23	  },
 24	}: IRequestParams): Promise<T> => {
 25	  const proxyURL = await getFrontendProxyURL();
 26	  const requestURL = `${proxyURL}${url}?${new URLSearchParams(queryParams).toString()}`;
 27	  const requestBody = body ? JSON.stringify(body) : undefined;
 28	  const response = await fetch(requestURL, {
 29	    method,
 30	    body: requestBody,
 31	    headers,
 32	  });
 33	
 34	  const responseText = await response.text();
 35	  let data;
 36	  try {
 37	    data = responseText ? JSON.parse(responseText) : undefined;
 38	  } catch (err) {
 39	    if (response.ok) {
 40	      throw err;
 41	    }
 42	    data = undefined;
 43	  }
 44	
 45	  if (!response.ok) {
 46	    throw new Error(data?.error || `Request failed with status ${response.status}`);
 47	  }
 48	
 49	  return data as T;
 50	};
 51	
 52	export default request;
