    39	fn init_tracer_provider() -> SdkTracerProvider {
    40	    global::set_text_map_propagator(TraceContextPropagator::new());
    41	
    42	    let tracer_provider = SdkTracerProvider::builder()
    43	        .with_resource(get_resource())
