    45	            opentelemetry_otlp::SpanExporter::builder()
    46	                .with_http()
    47	                .with_protocol(Protocol::HttpBinary)
    48	                .build()
    49	                .expect("Failed to initialize tracing provider"),
    50	        )
    51	        .build();
    52	
    53	    global::set_tracer_provider(tracer_provider.clone());
    54	    tracer_provider
    55	}
    56	
    57	fn init_meter_provider() -> SdkMeterProvider {
    58	    let meter_provider = SdkMeterProvider::builder()
    59	        .with_resource(get_resource())
    60	        .with_periodic_exporter(
    61	            opentelemetry_otlp::MetricExporter::builder()
