   100	/// Holds all OTel provider handles for graceful shutdown.
   101	pub struct OtelGuard {
   102	    tracer_provider: SdkTracerProvider,
   103	    logger_provider: SdkLoggerProvider,
   104	    meter_provider: SdkMeterProvider,
   105	}
   106	
   107	impl OtelGuard {
   108	    /// Shuts down all providers, flushing any buffered telemetry.
   109	    /// Order: tracer → logger → meter (meter last because BatchLogProcessor
   110	    /// may emit self-diagnostic metrics during its shutdown).
   111	    pub fn shutdown(self) {
   112	        if let Err(e) = self.tracer_provider.shutdown() {
   113	            eprintln!("Failed to shutdown TracerProvider: {e}");
   114	        }
   115	        if let Err(e) = self.logger_provider.shutdown() {
   116	            eprintln!("Failed to shutdown LoggerProvider: {e}");
   117	        }
   118	        if let Err(e) = self.meter_provider.shutdown() {
   119	            eprintln!("Failed to shutdown MeterProvider: {e}");
   120	        }
   121	    }
   122	}
   123	
   124	pub fn init_otel() -> Result<OtelGuard> {
   125	    let logger_provider = init_logger_provider();
   126	    let tracer_provider = init_tracer_provider();
   127	    let meter_provider = init_meter_provider();
   128	    Ok(OtelGuard {
   129	        tracer_provider,
   130	        logger_provider,
   131	        meter_provider,
   132	    })
   133	}
