 91	pub fn create_quote_from_float(value: f64) -> Quote {
 92	    let total_cents = (value * 100_f64).round() as u64;
 93	    Quote {
 94	        dollars: total_cents / 100,
 95	        cents: (total_cents % 100) as u32,
 96	    }
 97	}
