 36	// React Native 0.83's Performance API only supports the "mark" and "measure"
 37	// entry types; any other call to `performance.getEntriesByType()` emits a
 38	// "Deprecated API for given entry type" warning. `@opentelemetry/instrumentation-fetch`
 39	// falls back to `performance.getEntriesByType("resource")` for every request,
 40	// which makes the warning fire on every fetch even though the return value is
 41	// unused on mobile. Wrap the method so unsupported types return [] silently
 42	// while "mark"/"measure" continue to work.
 43	const originalGetEntriesByType = performance.getEntriesByType?.bind(performance);
 44	if (originalGetEntriesByType) {
 45	  performance.getEntriesByType = (entryType: string) => {
 46	    if (entryType !== "mark" && entryType !== "measure") {
 47	      return [];
 48	    }
 49	    return originalGetEntriesByType(entryType);
 50	  };
 51	}
