 53	export const setupTracerProvider = (proxyURL: string) => {
 54	  // TODO Should add a resource detector for React Native that provides this automatically
 55	  const resource = resourceFromAttributes({
 56	    [ATTR_SERVICE_NAME]: "react-native-app",
 57	    [ATTR_OS_NAME]: Platform.OS,
 58	    [ATTR_OS_VERSION]: getSystemVersion(),
 59	    [ATTR_SERVICE_VERSION]: getVersion(),
 60	    [ATTR_DEVICE_ID]: getUniqueIdSync(),
 61	  });
 62	
 63	  return new TracerProvider({
 64	    resource,
 65	    spanProcessors: [
 66	      new BatchSpanProcessor({
 67	          exporter: new OTLPTraceExporter({
 68	            url: `${proxyURL}/otlp-http/v1/traces`,
 69	          }),
 70	          scheduledDelayMillis: 500,
 71	        },
 72	      ),
 73	      // TODO introduce a React Native session processor package that could be used here, taking into account mobile
 74	      // specific considerations for the session such as putting the app into the background
 75	      new SessionIdProcessor(),
 76	    ],
 77	  });
 78	}
