 81	  const proxyURL = await getFrontendProxyURL();
 82	
 83	  context.setGlobalContextManager(new StackContextManager().enable());
 84	  propagation.setGlobalPropagator(new CompositePropagator({
 85	    propagators: [
 86	      new W3CBaggagePropagator(),
