 92	  registerInstrumentations({
 93	    instrumentations: [
 94	      // TODO Some tiptoeing required here, propagateTraceHeaderCorsUrls is required to make the instrumentation
 95	      // work in the context of a mobile app even though we are not making CORS requests. `clearTimingResources` must
 96	      // be turned off to avoid using the web-only Performance API
 97	      // Overall wrapping or forking this and providing a React Native specific auto instrumentation will ease
 98	      // integration and make it less error-prone
 99	      new FetchInstrumentation({
100	        propagateTraceHeaderCorsUrls: /.*/,
101	        clearTimingResources: false,
102	      }),
103	
104	      // The React Native implementation of fetch is simply a polyfill on top of XMLHttpRequest:
105	      // https://github.com/facebook/react-native/blob/7ccc5934d0f341f9bc8157f18913a7b340f5db2d/packages/react-native/Libraries/Network/fetch.js#L17
106	      // Because of this when making requests using `fetch` there will an additional span created for the underlying
107	      // request made with XMLHttpRequest. Since in this demo calls to /api/ are made using fetch, turn off
108	      // instrumentation for that path to avoid the extra spans.
